char* parse_content_length(char* const buffer, const char* const end,
                int* const length)
{
        int number;
        char *p;
        int  size;

        p = buffer;
        /* search the begining of the number */
        while ( p<end && (*p==' ' || *p=='\t' ||
        (*p=='\n' && (*(p+1)==' '||*(p+1)=='\t')) ))
                p++;
        if (p==end)
                goto error;
        /* parse the number */
        size = 0;
        number = 0;
        while (p<end && *p>='0' && *p<='9') {
                number = number*10 + (*p)-'0';
                size ++;
                p++;
        }
        if (p==end || size==0)
                goto error;
        /* now we should have only spaces at the end */
        while ( p<end && (*p==' ' || *p=='\t' ||
        (*p=='\n' && (*(p+1)==' '||*(p+1)=='\t')) ))
                p++;
        if (p==end)
                goto error;
        /* the header ends proper? */
        if ( (*(p++)!='\n') && (*(p-1)!='\r' || *(p++)!='\n' ) )
                goto error;

        *length = number;
        return p;
error:
        LM_ERR("parse error near char [%d][%c]\n", *p, *p);
        return 0;
}



char* decode_mime_type(char* const start, const char* const end,
                unsigned int* const mime_type)
{
        int node;
        char *mark;
        char *p;
        unsigned int type_candidate;

        p = start;

        /* search the begining of the type */
        while ( p<end && (*p==' ' || *p=='\t' ||
        (*p=='\n' && (*(p+1)==' '||*(p+1)=='\t')) ))
                p++;
        if (p==end)
                goto error;

        /* parse the type */
        if (*p=='*') {
                *mime_type = TYPE_ALL<<16;
                p++;
        } else {
                node = 0;
                mark = p;
                type_candidate = TYPE_UNKNOWN;
